237	     * due, and records it in the audit; empty if no such invoice. The amount has already been
238	     * checked; a draft, an invoice already paid, an amount over what is due, or a date after today
239	     * or before the invoice's issue date is refused. The reference (null when none was quoted) has
240	     * already been checked; one that belongs to a different invoice is refused.
241	     */
242	    @Transactional
243	    public Optional<Invoice> recordPayment(Long invoiceId, BigDecimal amount, LocalDate date, String reference) {
244	        Optional<Invoice> found = invoices.findWithLinesById(invoiceId);
245	        found.ifPresent(invoice -> {
246	            if (invoice.isDraft()) {
247	                throw new InvoiceRejectedException("Send the invoice before recording a payment.");
248	            }
249	            if (invoice.isVoid()) {
250	                throw new InvoiceRejectedException("A void invoice takes no payments.");
251	            }
252	            BigDecimal due = invoice.amountDue(paid(List.of(invoice)).get(invoice.getId()), taxRate.percent());
253	            if (due.signum() <= 0) {
254	                throw new InvoiceRejectedException("This invoice has already been paid.");
255	            }
256	            if (amount.compareTo(due) > 0) {
257	                throw new InvoiceRejectedException("The payment is more than the $" + due.toPlainString() + " due.");
258	            }
259	            LocalDate now = today.date();
260	            if (date.isAfter(now)) {
261	                throw new InvoiceRejectedException("The payment date cannot be after today (" + now + ").");
262	            }
263	            if (invoice.getIssueDate() != null && date.isBefore(invoice.getIssueDate())) {
264	                throw new InvoiceRejectedException(
265	                        "The payment date cannot be before the invoice's issue date (" + invoice.getIssueDate() + ").");
266	            }
267	            if (reference != null && !reference.equals(PaymentReference.of(invoice.getId()))) {
268	                throw new InvoiceRejectedException(PaymentReference.grouped(reference)
269	                        + " is the reference of a different invoice; this invoice's is "
270	                        + PaymentReference.grouped(PaymentReference.of(invoice.getId())) + ".");
271	            }
272	            Payment payment = payments.saveAndFlush(Payment.against(invoice, amount, date, reference));
273	            audit.record("PAYMENT_RECORDED id=" + payment.getId() + " invoice=" + invoice.getId() + " amount="
274	                    + amount.setScale(2, RoundingMode.UNNECESSARY).toPlainString());
275	        });
276	        return found;
277	    }
278	
279	    /**
280	     * Records one payment of the amount on the date against the client's unpaid sent invoices, earliest
281	     * due date first (lower id first on the same due date) so overdue invoices are cleared first,
282	     * paying each off in full before the next.
283	     * A payment more than everything the client owes is refused; otherwise it is checked and recorded
284	     * as a split payment over the invoices it reaches.
285	     */
286	    @Transactional
287	    public Payment recordAutoPayment(Long clientId, BigDecimal amount, LocalDate date, String reference) {
288	        List<Invoice> sent = invoices.findByClientIdOrderByIdAsc(clientId).stream()
289	                .filter(i -> !i.isDraft() && !i.isVoid())
290	                .sorted(Comparator.comparing(Invoice::getDueDate, Comparator.nullsLast(Comparator.naturalOrder()))
291	                        .thenComparing(Invoice::getId))
292	                .toList();
293	        Map<Long, BigDecimal> paid = paid(sent);
294	        BigDecimal owed = BigDecimal.ZERO;
295	        BigDecimal left = amount;
296	        List<PaymentAllocation> parts = new ArrayList<>();
297	        for (Invoice invoice : sent) {
298	            BigDecimal due = invoice.amountDue(paid.get(invoice.getId()), taxRate.percent());
299	            if (due.signum() <= 0) {
300	                continue;
301	            }
302	            owed = owed.add(due);
303	            if (left.signum() > 0) {
304	                BigDecimal part = left.min(due);
305	                parts.add(new PaymentAllocation(invoice.getId(), part));
306	                left = left.subtract(part);
307	            }
308	        }
309	        if (owed.signum() <= 0) {
310	            throw new InvoiceRejectedException("The client has no unpaid invoices to pay.");
311	        }
312	        if (left.signum() > 0) {
313	            throw new InvoiceRejectedException("The payment is more than the $" + owed.setScale(2).toPlainString()
314	                    + " the client owes.");
315	        }
316	        return recordSplitPayment(clientId, amount, date, reference, parts);
317	    }
318	
319	    /**
320	     * Records one payment of the amount on the date spread over several of the client's invoices, and
321	     * records each part in the audit. The amounts have already been checked to be more than zero; they
322	     * must add up exactly to the payment, and each must go to a different sent invoice of the client
323	     * and be no more than what it still has due. The date must be no later than today nor before any
324	     * of the invoices' issue dates. The reference (null when none) has already been checked; it must
325	     * be the reference of one of the invoices.
326	     */
327	    @Transactional
328	    public Payment recordSplitPayment(Long clientId, BigDecimal amount, LocalDate date, String reference,
329	            List<PaymentAllocation> parts) {
330	        if (parts.isEmpty()) {
331	            throw new InvoiceRejectedException("Enter how much of the payment goes to each invoice.");
332	        }
333	        BigDecimal sum = parts.stream().map(PaymentAllocation::getAmount).reduce(BigDecimal.ZERO, BigDecimal::add);
334	        if (sum.compareTo(amount) != 0) {
335	            throw new InvoiceRejectedException("The amounts for the invoices add up to $"
336	                    + sum.setScale(2).toPlainString() + ", not the $" + amount.setScale(2).toPlainString() + " paid.");
337	        }
338	        LocalDate now = today.date();
339	        if (date.isAfter(now)) {
340	            throw new InvoiceRejectedException("The payment date cannot be after today (" + now + ").");
341	        }
342	        Set<Long> seen = new HashSet<>();
343	        List<Invoice> spreadOver = new ArrayList<>();
344	        for (PaymentAllocation part : parts) {
345	            if (!seen.add(part.getInvoiceId())) {
346	                throw new InvoiceRejectedException("Each invoice can take only one part of the payment.");
347	            }
348	            Invoice invoice = invoices.findWithLinesById(part.getInvoiceId())
349	                    .filter(i -> i.getClientId().equals(clientId))
350	                    .orElseThrow(() -> new InvoiceRejectedException("A part of the payment goes to an invoice of another client."));
351	            String number = InvoiceNumber.of(invoice.getId());
352	            if (invoice.isDraft()) {
353	                throw new InvoiceRejectedException("Send " + number + " before recording a payment against it.");
354	            }
355	            if (invoice.isVoid()) {
356	                throw new InvoiceRejectedException(number + " is void and takes no payments.");
357	            }
358	            BigDecimal due = invoice.amountDue(paid(List.of(invoice)).get(invoice.getId()), taxRate.percent());
359	            if (part.getAmount().compareTo(due) > 0) {
360	                throw new InvoiceRejectedException("The $" + part.getAmount().setScale(2).toPlainString() + " for "
361	                        + number + " is more than the $" + due.toPlainString() + " it has due.");
362	            }
363	            if (invoice.getIssueDate() != null && date.isBefore(invoice.getIssueDate())) {
364	                throw new InvoiceRejectedException("The payment date cannot be before the issue date of " + number
365	                        + " (" + invoice.getIssueDate() + ").");
366	            }
367	            spreadOver.add(invoice);
368	        }
369	        if (reference != null && spreadOver.stream().noneMatch(i -> reference.equals(PaymentReference.of(i.getId())))) {
370	            throw new InvoiceRejectedException(PaymentReference.grouped(reference)
371	                    + " is not the reference of any of the invoices being paid.");
372	        }
373	        Payment payment = payments.saveAndFlush(Payment.split(clientId, amount, date, reference, parts));
374	        for (PaymentAllocation part : parts) {
375	            audit.record("PAYMENT_RECORDED id=" + payment.getId() + " invoice=" + part.getInvoiceId() + " amount="
376	                    + part.getAmount().setScale(2, RoundingMode.UNNECESSARY).toPlainString());
377	        }
378	        return payment;
379	    }
380	
381	    /**
382	     * Reverses the payment (a bounced cheque), undoing it on every invoice it was applied to, and
383	     * records it in the audit; empty if no such payment. A payment already reversed is refused.
384	     */
385	    @Transactional
386	    public Optional<Payment> reversePayment(Long paymentId) {
387	        Optional<Payment> found = payments.findById(paymentId);
388	        found.ifPresent(payment -> {
389	            if (payment.isReversed()) {
390	                throw new InvoiceRejectedException("This payment has already been reversed.");
391	            }
392	            payment.reverse();
393	            payments.saveAndFlush(payment);
394	            audit.record("PAYMENT_REVERSED id=" + payment.getId() + " amount="
395	                    + payment.getAmount().setScale(2, RoundingMode.UNNECESSARY).toPlainString());
396	        });
397	        return found;
398	    }
399	}
